def earliest_full_friendship(logs, n):
 parent=list(range(n));groups=n
 def find(x):
  while parent[x]!=x:parent[x]=parent[parent[x]];x=parent[x]
  return x
 for time,x,y in sorted(logs):
  x,y=find(x),find(y)
  if x!=y:parent[x]=y;groups-=1
  if groups==1:return time
 return -1

